def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not pts:
        return out
    top, bottom = min(r for r, c in pts), max(r for r, c in pts)
    left, right = min(c for r, c in pts), max(c for r, c in pts)
    # Complete the outside rectangular frame.
    for c in range(left, right + 1):
        for r in (top, bottom):
            if grid[r][c] == bg:
                out[r][c] = 2
    for r in range(top, bottom + 1):
        for c in (left, right):
            if grid[r][c] == bg:
                out[r][c] = 2
    # Complete interior broken straight lines when they contain at least 3 marks.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] != bg]
        if len(cols) >= 3:
            for c in range(cols[0], cols[-1] + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] != bg]
        if len(rows) >= 3:
            for r in range(rows[0], rows[-1] + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out
